import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CustomersService } from './customers.service';

@Component({
  selector: 'app-customers',
  templateUrl: './customers.component.html',
  styleUrls: ['./customers.component.css'],
})
export class CustomersComponent implements OnInit {
  customers: any[] = [];
  showForm = false;
  exibirModal = false; // Controle para exibir o modal de confirmação
  customerForm: FormGroup;
  actionType: string = ''; // Define se a ação é de adição ou exclusão
  customerToDelete: any = null; // Armazena o cliente a ser excluído
  customerToAdd: any = null; // Armazena o cliente a ser adicionado

  constructor(private service: CustomersService, private fb: FormBuilder) {
    this.customerForm = this.fb.group({
      name: ['', [Validators.required, Validators.maxLength(50)]],
      address: ['', [Validators.required, Validators.maxLength(100)]],
      number: ['', [Validators.required, Validators.maxLength(10)]],
      district: ['', Validators.maxLength(50)],
      phone: ['', [Validators.required, Validators.maxLength(15)]],
    });
  }

  ngOnInit(): void {
    this.getCustomers();
  }

  getCustomers(): void {
    this.service.findAll().subscribe((res: any) => {
      this.customers = res.result;
    });
  }

  toggleFormulario(): void {
    this.showForm = !this.showForm;
    if (!this.showForm) {
      this.customerForm.reset();
    }
  }

  adicionarCliente(): void {
    if (this.customerForm.valid) {
      this.customerToAdd = { ...this.customerForm.value };
      this.actionType = 'adicionar';  // Ação de adicionar
      this.toggleModal();  // Exibe o modal de confirmação
    }
  }

  confirmarExclusao(customer: any): void {
    this.customerToDelete = customer;
    this.actionType = 'excluir';  // Ação de excluir
    this.toggleModal();  // Exibe o modal de confirmação
  }

  toggleModal(): void {
    this.exibirModal = !this.exibirModal;
  }

  confirmarAcoes(): void {
    if (this.actionType === 'adicionar' && this.customerToAdd) {
      // Adiciona o cliente
      this.service.create(this.customerToAdd).subscribe(() => {
        this.getCustomers();
        this.toggleFormulario();  // Fecha o formulário
        this.toggleModal();  // Fecha o modal de confirmação
      });
    } else if (this.actionType === 'excluir' && this.customerToDelete) {
      // Exclui o cliente
      this.service.delete(this.customerToDelete.id.toString()).subscribe(() => {
        this.getCustomers();
        this.toggleModal();  // Fecha o modal de confirmação
      });
    }
  }

  cancelarAcoes(): void {
    console.log('Ação cancelada.');
    this.toggleModal();  // Fecha o modal sem fazer nada
  }
}
<app-page-body>
  <h2>Clientes</h2>

  <button (click)="toggleFormulario()" class="btn-new-customer">
    Novo Cliente
  </button>


  <div *ngIf="showForm" class="modal-overlay">
    <div class="modal-content">
      <span class="close-btn" (click)="toggleFormulario()">&times;</span>
      <h2>Cadastrar Cliente</h2>
      <form [formGroup]="customerForm" (ngSubmit)="adicionarCliente()">
        <label for="name">Nome:</label>
        <input id="name" formControlName="name" required />

        <label for="address">Endereço:</label>
        <input id="address" formControlName="address" required />

        <label for="number">Número:</label>
        <input id="number" formControlName="number" required />

        <label for="district">Bairro:</label>
        <input id="district" formControlName="district" />

        <label for="phone">Telefone:</label>
        <input id="phone" formControlName="phone" required />

        <button type="submit" [disabled]="customerForm.invalid">
          Cadastrar
        </button>
      </form>
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th>Id</th>
        <th>Nome</th>
        <th>Endereço</th>
        <th>Número</th>
        <th>Bairro</th>
        <th>Telefone</th>
        <th>Criado em</th>
        <th>Ações</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let customer of customers">
        <td>{{ customer.id }}</td>
        <td>{{ customer.name }}</td>
        <td>{{ customer.address }}</td>
        <td>{{ customer.number }}</td>
        <td>{{ customer.district || '-' }}</td>
        <td>{{ customer.phone }}</td>
        <td>{{ customer.createdAt | date: 'short' }}</td>
        <td>
          <button class="btn-icon delete-btn" (click)="confirmarExclusao(customer)">
            <i class="fa fa-trash"></i>
          </button>
        </td>
      </tr>
    </tbody>
  </table>

  <p *ngIf="customers.length === 0">Nenhum cliente cadastrado.</p>

  <!-- Modal de confirmação -->
  <app-modal
    [visible]="exibirModal"
    title="Confirmação"
    message="Deseja realmente {{ actionType }} este cliente?"
    (onConfirm)="confirmarAcoes()"
    (onCancel)="cancelarAcoes()"
  ></app-modal>
</app-page-body>
